import boto3

s3 = boto3.client("s3")
BUCKET = "my-data-lake"
PREFIX = "staging/events/2026-06-01/"

def iter_parquet_keys(bucket: str, prefix: str):
    paginator = s3.get_paginator("list_objects_v2")
    # PaginationConfig.PageSize controls keys per API call (max 1000)
    pages = paginator.paginate(
        Bucket=bucket,
        Prefix=prefix,
        PaginationConfig={"PageSize": 1000},
    )
    for page in pages:
        for obj in page.get("Contents", []):
            if obj["Key"].endswith(".parquet"):
                yield obj["Key"], obj["Size"]

def main() -> None:
    count = 0
    total_bytes = 0
    for key, size in iter_parquet_keys(BUCKET, PREFIX):
        count += 1
        total_bytes += size
    print(f"{count} parquet objects, {total_bytes / 1e9:.2f} GB under {PREFIX}")

if __name__ == "__main__":
    main()
